// Proxy editing (P2, M4): FCP-style proxies. A clip keeps its
// ORIGINAL file as `source`; `proxy` points at a low-resolution
// stand-in generated by generateProxy (720p, low bitrate) that the
// timeline / preview renders against. Export ALWAYS renders from the
// original source — that is the relink — but it refuses to export when
// a declared proxy file is missing or does not match its declaration,
// instead of silently falling back to the original: a missing proxy
// means the edit was made against footage the editor can no longer
// see, and the caller must be told, not papered over.
//
// Measured behaviour (probe 2026-11-17, FFmpeg 8.1.2):
// - generateProxy(1920x1080 testsrc, crf 28, 1280x720) keeps the
//   source duration (err < 0.1 s) and drops the bitrate well below the
//   original; the exact numbers are in verify-p2c.
// - A proxy-as-source export vs the original-source export stays
//   close (PSNR >= 35 in the probe) but is NOT identical — so the
//   verify-p2c relink check (proxy-attached export vs direct export,
//   PSNR 999) genuinely proves the engine rendered the original.
// LGPL note: generateProxy uses scale / libx264 / aac — libx264 is a
// GPL encoder, so the proxy GENERATION step is not LGPL; the export
// path itself adds no new filter (the proxy is only validated, never
// rendered). Only verified on the local GPL 8.1.2 build; re-check on
// the BtbN LGPL 9.0 build at the M2 gate.

import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { existsSync } from 'node:fs';
import type { Clip, Project } from './project.js';

const execFileAsync = promisify(execFile);

/** A proxy reference on a clip: the stand-in file + its real size. */
export interface ProxyRef {
  /** Path to the generated proxy file. */
  file: string;
  /** Proxy frame width in px (must match the file). */
  width: number;
  /** Proxy frame height in px (must match the file). */
  height: number;
}

export interface ProxyInfo {
  file: string;
  width: number;
  height: number;
  /** Total (format) bitrate in bits/s, ffprobe-measured. */
  bitrate: number;
  /** Proxy duration in seconds, ffprobe-measured. */
  duration: number;
  /** Source duration in seconds, ffprobe-measured. */
  sourceDuration: number;
}

export const PROXY_DEFAULT_WIDTH = 1280;
export const PROXY_DEFAULT_HEIGHT = 720;
export const PROXY_DEFAULT_CRF = 28;
/** Proxy duration must match the source duration within this (s). */
export const PROXY_DURATION_TOLERANCE = 0.1;

export interface GenerateProxyOptions {
  ffmpeg?: string;
  ffprobe?: string;
  /** Target width (default 1280). Only downscales: a source smaller
   *  than the target keeps its own size (scale min(..., iw)). */
  width?: number;
  /** Target height (default 720). */
  height?: number;
  /** x264 CRF for the proxy video (default 28). */
  crf?: number;
  /** Proxy audio bitrate (default '96k'). */
  audioBitrate?: string;
}

interface MediaProbe {
  duration: number;
  width: number;
  height: number;
  bitrate: number;
  hasAudio: boolean;
}

async function probeMedia(file: string, ffprobe: string): Promise<MediaProbe> {
  const { stdout } = await execFileAsync(ffprobe, [
    '-v', 'error', '-select_streams', 'v:0',
    '-show_entries', 'stream=width,height',
    '-show_entries', 'format=duration,bit_rate',
    '-of', 'json', file,
  ]);
  const data = JSON.parse(stdout) as {
    streams: { width: number; height: number }[];
    format: { duration: string; bit_rate: string };
  };
  if (!data.streams[0]) {
    throw new Error(`proxy probe: no video stream in ${file}`);
  }
  let hasAudio = false;
  try {
    const { stdout: aout } = await execFileAsync(ffprobe, [
      '-v', 'error', '-select_streams', 'a', '-show_entries', 'stream=index', '-of', 'csv=p=0', file,
    ]);
    hasAudio = aout.trim().length > 0;
  } catch {
    hasAudio = false;
  }
  return {
    duration: Number(data.format.duration),
    width: data.streams[0].width,
    height: data.streams[0].height,
    bitrate: Number(data.format.bit_rate),
    hasAudio,
  };
}

/**
 * Generate a low-resolution proxy for a source file. The proxy keeps
 * the source's duration and fps, is scaled down to at most width x
 * height (aspect preserved, even dimensions), and is encoded at a low
 * CRF so its bitrate lands well below the original's. Returns the
 * measured proxy info — store `file`/`width`/`height` from it in
 * Clip.proxy so validateProxies can check the file against the
 * declaration later. Throws when the source cannot be probed or the
 * encode fails.
 */
export async function generateProxy(
  source: string,
  output: string,
  opts: GenerateProxyOptions = {},
): Promise<ProxyInfo> {
  const ffmpeg = opts.ffmpeg ?? 'ffmpeg';
  const ffprobe = opts.ffprobe ?? 'ffprobe';
  const width = opts.width ?? PROXY_DEFAULT_WIDTH;
  const height = opts.height ?? PROXY_DEFAULT_HEIGHT;
  const crf = opts.crf ?? PROXY_DEFAULT_CRF;
  const src = await probeMedia(source, ffprobe);
  const args = [
    '-v', 'error', '-i', source,
    '-vf', `scale='min(${width},iw)':-2`,
    '-c:v', 'libx264', '-preset', 'veryfast', '-crf', String(crf),
    '-pix_fmt', 'yuv420p',
  ];
  if (src.hasAudio) args.push('-c:a', 'aac', '-b:a', opts.audioBitrate ?? '96k');
  else args.push('-an');
  args.push('-y', output);
  await execFileAsync(ffmpeg, args, { maxBuffer: 64 * 1024 * 1024 });
  const proxy = await probeMedia(output, ffprobe);
  return {
    file: output,
    width: proxy.width,
    height: proxy.height,
    bitrate: proxy.bitrate,
    duration: proxy.duration,
    sourceDuration: src.duration,
  };
}

/**
 * Validate every clip proxy before export. Throws on: a proxy on a
 * compound or multicam clip (v1 does not support it); a missing proxy
 * file — the message says the proxy is lost and names the file, and
 * the export is refused rather than silently rendering the original;
 * a proxy whose measured size differs from the declared width/height;
 * a proxy whose duration differs from its source file's duration by
 * more than PROXY_DURATION_TOLERANCE. No-op for projects with no
 * proxies. Call before the graph build (export.ts does this in
 * exportProjectInner).
 */
export async function validateProxies(project: Project, ffprobe = 'ffprobe'): Promise<void> {
  for (const clip of project.clips) {
    const proxy = clip.proxy;
    if (!proxy) continue;
    if (clip.compound) {
      throw new Error(`clip ${clip.id}: proxy is not supported on compound clips in v1`);
    }
    if (clip.multicam) {
      throw new Error(`clip ${clip.id}: proxy is not supported on multicam clips in v1`);
    }
    if (!proxy.file || typeof proxy.file !== 'string') {
      throw new Error(`clip ${clip.id}: proxy.file is required`);
    }
    if (!existsSync(proxy.file)) {
      throw new Error(
        `clip ${clip.id}: proxy file missing: ${proxy.file} — the timeline was ` +
          `edited against this proxy, refusing to silently fall back to the original; ` +
          `regenerate the proxy or remove clip.proxy`,
      );
    }
    const measured = await probeMedia(proxy.file, ffprobe);
    if (measured.width !== proxy.width || measured.height !== proxy.height) {
      throw new Error(
        `clip ${clip.id}: proxy size mismatch: declared ${proxy.width}x${proxy.height} ` +
          `but file ${proxy.file} is ${measured.width}x${measured.height}`,
      );
    }
    const src = await probeMedia(clip.source, ffprobe);
    if (Math.abs(measured.duration - src.duration) > PROXY_DURATION_TOLERANCE) {
      throw new Error(
        `clip ${clip.id}: proxy duration ${measured.duration.toFixed(3)}s differs from ` +
          `source duration ${src.duration.toFixed(3)}s by more than ${PROXY_DURATION_TOLERANCE}s`,
      );
    }
  }
}

/**
 * Return a copy of the project with every proxied clip's source
 * swapped to its proxy file — the fast preview render path (what the
 * timeline shows while editing). Throws on a missing proxy file.
 * Export never uses this: exportProject always renders from the
 * original source (the relink), after validateProxies has confirmed
 * the proxy still exists.
 */
export function useProxies(project: Project): Project {
  const clips: Clip[] = project.clips.map((clip) => {
    if (!clip.proxy) return clip;
    if (!existsSync(clip.proxy.file)) {
      throw new Error(`clip ${clip.id}: proxy file missing: ${clip.proxy.file}`);
    }
    return { ...clip, source: clip.proxy.file };
  });
  return { ...project, clips };
}
